package dev.zomboidmelee.boxing;
import net.minecraft.client.model.PlayerModel;import net.minecraft.client.model.geom.ModelPart;import net.minecraft.client.Minecraft;
public class SlideVisualChecks28 {
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 public static void main(String[]args){var p=new MovementChecks26.Local();var model=new PlayerModel<Object>();model.body=new ModelPart();model.head=new ModelPart();model.hat=new ModelPart();model.rightArm=new ModelPart();model.leftArm=new ModelPart();model.rightLeg=new ModelPart();model.leftLeg=new ModelPart();model.jacket=new ModelPart();model.rightPants=new ModelPart();model.leftPants=new ModelPart();model.rightSleeve=new ModelPart();model.leftSleeve=new ModelPart();model.body.xRot=.13f;float initial=model.body.xRot;ok(SlidePose28.apply(model,p,1),"new slide animation handles humanoid player");ok(model.body.y==18&&model.body.xRot<-1.1&&model.rightLeg.xRot<-1.4,"torso lies back and leg extends rather than sitting upright");ok(model.rightLeg.y>21&&model.head.y>18,"whole skeleton is low enough for the tunnel");ok(model.head.y==model.hat.y&&model.body.y==model.jacket.y&&model.rightLeg.y==model.rightPants.y,"hat, clothing and pants follow the slide pose");SlidePose28.restore(model);ok(model.body.y==0&&model.body.xRot==initial&&model.head.y==0&&model.rightLeg.y==0,"temporary pivots restored before next vanilla animation");ok(!SlidePose28.BASE.containsKey(model),"restored snapshot releases all state");
 Minecraft mc=Minecraft.INSTANCE;mc.player=p;mc.level=p.physics;mc.screen=null;long[] clock={5_000_000_000L};BoxingClient16.CLOCK=()->clock[0];Bodycam26.tick(p,p.physics);Bodycam27.sample(0);clock[0]+=16_666_667;Bodycam27.sample(0);long sampled=Bodycam27.sampled;clock[0]+=1_000_000;Bodycam27.sample(.5f);ok(Bodycam27.sampled==sampled,"world and weapon rendering share one motion sample per frame");
 // Baseline low-ready is removed continuously as ADS reaches one.
 for(int i=0;i<120;i++){clock[0]+=16_666_667;Bodycam27.sample(0);}double hip=Math.abs(Bodycam27.GUN[1].value);mc.options.keyUse.down=true;for(int i=0;i<120;i++){clock[0]+=16_666_667;Bodycam27.sample(0);}ok(hip>.02&&Math.abs(Bodycam27.GUN[1].value)<hip*.08,"reference-style lower weapon position yields to ADS alignment");System.out.println("NEW_LOW_SLIDE_POSE_LAYER_RESET_SHARED_FRAME_LOW_READY_CHECKS="+n);}
}
